{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "framework": "nextjs",
  "redirects": [
    {
      "source": "/:path*",
      "has": [{ "type": "host", "value": "www.peninganaedalifid.is" }],
      "destination": "https://peninganaedalifid.is/:path*",
      "permanent": true
    }
  ],
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        {
          "key": "X-Content-Type-Options",
          "value": "nosniff"
        },
        {
          "key": "X-Frame-Options",
          "value": "DENY"
        },
        {
          "key": "X-XSS-Protection",
          "value": "1; mode=block"
        },
        {
          "key": "Referrer-Policy",
          "value": "strict-origin-when-cross-origin"
        }
      ]
    },
    {
      "source": "/(.*)\\.(js|css|woff2?|png|jpg|jpeg|gif|ico|svg)",
      "headers": [
        {
          "key": "Cache-Control",
          "value": "public, max-age=31536000, immutable"
        }
      ]
    }
  ],
  "trailingSlash": false,
  "cleanUrls": true
}

import { Metadata } from 'next';
import { CalculatorProvider } from '@/context/CalculatorContext';
import { CalculatorPageContent } from '@/components/calculator';

export const metadata: Metadata = {
  title: 'Peningana eða lífið - Þín leið að fjárhagslegu frelsi',
  description: 'Reiknaðu raunverulegt tímakaup þitt með því að taka tillit til alls falins vinnukostnaðar og tíma. Byggt á aðferðafræði Your Money or Your Life.',
};

export default function CalculatorPage() {
  return (
    <CalculatorProvider>
      <CalculatorPageContent />
    </CalculatorProvider>
  );
}

